'use strict';

/**
 * audit-firestore-invoices.js — READ-ONLY audit of the `invoices` Firestore
 * collection (the list the AvyCloud app shows). Finds duplicate docs for the
 * same invoice number — typically one "rich" doc (generated by AvyCloud, has
 * orderId + customer + pdfUrl) plus a "sparse" leftover from importFromSevDesk
 * (source=sevdesk_import, customer null, no order, no pdf).
 *
 * It NEVER writes. No --apply flag. Use the output to plan a safe dedupe.
 *
 * Usage:
 *   node backend/scripts/audit-firestore-invoices.js
 *   node backend/scripts/audit-firestore-invoices.js --json
 */

const { Firestore } = require('@google-cloud/firestore');

const TENANT = process.env.TENANT_ID || 'default';
const JSON_OUT = process.argv.includes('--json');

// "Richness" — how much real data a doc carries. Higher = more authoritative.
function richness(d) {
  let s = 0;
  if (d.orderId) s += 3;
  if (d.pdfUrl) s += 3;
  if (d.customer && (d.customer.street || d.customer.city)) s += 2;
  else if (d.customer && d.customer.name) s += 1;
  if (Array.isArray(d.items) && d.items.length) s += 1;
  if (d.source === 'sevdesk_import') s -= 2; // import leftovers are the sparse ones
  return s;
}

(async () => {
  const db = new Firestore();
  const snap = await db.collection('invoices').where('tenantId', '==', TENANT).get();
  const docs = snap.docs.map((d) => ({ id: d.id, ...d.data() }));

  const byNumber = new Map();
  const blank = [];
  for (const d of docs) {
    const num = (d.invoiceNumber || '').trim();
    if (!num) { blank.push(d); continue; }
    if (!byNumber.has(num)) byNumber.set(num, []);
    byNumber.get(num).push(d);
  }

  const dupGroups = [];
  let deletableSparse = 0;
  for (const [num, list] of byNumber.entries()) {
    if (list.length < 2) continue;
    // Pick the richest doc to KEEP; the rest are deletion candidates.
    const sorted = [...list].sort((a, b) => richness(b) - richness(a));
    const keep = sorted[0];
    const drop = sorted.slice(1);
    deletableSparse += drop.length;
    dupGroups.push({
      number: num,
      count: list.length,
      keepId: keep.id,
      keepRichness: richness(keep),
      dropIds: drop.map((d) => d.id),
      dropAreImport: drop.every((d) => d.source === 'sevdesk_import'),
      sameSevdeskId: list.every((d) => d.sevdeskId && d.sevdeskId === list[0].sevdeskId),
    });
  }

  const importDocs = docs.filter((d) => d.source === 'sevdesk_import').length;
  const report = {
    totalDocs: docs.length,
    uniqueNumbers: byNumber.size,
    blankNumberDocs: blank.length,
    duplicateNumberGroups: dupGroups.length,
    deletableDuplicateDocs: deletableSparse,
    importDocsTotal: importDocs,
  };

  if (JSON_OUT) {
    console.log(JSON.stringify({ report, dupGroups, blank: blank.map((d) => ({ id: d.id, sevdeskId: d.sevdeskId || null, source: d.source || null })) }, null, 2));
    return;
  }

  const line = (n) => '─'.repeat(n);
  console.log(`\n${line(64)}`);
  console.log('  Firestore-Rechnungsliste — Audit (READ-ONLY, App-Datenbank)');
  console.log(`${line(64)}\n`);
  console.log(`  Rechnungs-Docs gesamt        : ${report.totalDocs}`);
  console.log(`  Eindeutige Nummern           : ${report.uniqueNumbers}`);
  console.log(`  Docs ohne Nummer (leer)      : ${report.blankNumberDocs}`);
  console.log(`  Nummern mit mehreren Docs    : ${report.duplicateNumberGroups}`);
  console.log(`  → löschbare Doppel-Docs      : ${report.deletableDuplicateDocs}  (sparsamster behalten? nein — reichster behalten)`);
  console.log(`  Import-Docs (sevdesk_import) : ${report.importDocsTotal}\n`);

  if (dupGroups.length) {
    console.log(`${line(64)}`);
    console.log('  Doppelte Nummern (behalten → löschen):');
    console.log(`${line(64)}`);
    for (const g of dupGroups.slice(0, 60)) {
      const flag = g.dropAreImport ? 'Import-Rest' : (g.sameSevdeskId ? 'gleiche SevDesk-ID' : 'PRÜFEN');
      console.log(`  ${g.number.padEnd(10)} ${g.count}×  behalte ${g.keepId} (Score ${g.keepRichness}) → lösche ${g.dropIds.join(', ')}  [${flag}]`);
    }
    if (dupGroups.length > 60) console.log(`  … und ${dupGroups.length - 60} weitere`);
    console.log('');
  }

  console.log(`${line(64)}`);
  console.log('  Hinweis: Dies betrifft NUR die AvyCloud-Datenbank (App-Liste),');
  console.log('  NICHT SevDesk. Einzelne Import-Docs ohne Doppel bleiben unberührt.');
  console.log('  Nichts wurde verändert. Lösch-Skript folgt erst nach Freigabe.\n');
})().catch((err) => {
  console.error(`[audit-firestore-invoices] ${err.message}`);
  process.exit(1);
});
